mapper.select:
SELECT l.*, CASE WHEN u.real_name IS NOT NULL THEN CONCAT(u.real_name, ' (', u.username, ')') ELSE u.username END AS operator FROM sys_operation_log l LEFT JOIN sys_user u ON u.id = l.user_id WHERE 1=1
AND l.tenant_id = #{tenantId}
AND l.module LIKE CONCAT('%', #{module}, '%')
AND l.action LIKE CONCAT('%', #{action}, '%')
AND (CASE WHEN u.real_name IS NOT NULL THEN CONCAT(u.real_name, ' (', u.username, ')') ELSE u.username END) LIKE CONCAT('%', #{operator}, '%')
AND l.is_success = #{isSuccess}
AND l.operation_time >= #{startTime}
AND l.operation_time <= #{endTime}
ORDER BY operator ${sortOrder}
ORDER BY l.${sortField} ${sortOrder}
ORDER BY l.operation_time DESC
